-- table: sys_area（由 cmd/schema-split 生成；改结构直接改本文件）

-- @phase ddl
CREATE TABLE public.sys_area (
    code character varying(16) NOT NULL,
    kind character varying(16) NOT NULL,
    level smallint NOT NULL,
    parent_code character varying(16),
    name_zh character varying(128) NOT NULL,
    name_en character varying(128),
    iso_code character varying(16),
    alpha3 character varying(3),
    numeric_code character varying(8),
    dial_code character varying(8),
    default_currency character varying(8),
    default_lang character varying(16),
    source character varying(32) DEFAULT 'manual'::character varying NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    create_time timestamp with time zone DEFAULT now() NOT NULL,
    update_time timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_sys_area_kind CHECK (((kind)::text = ANY ((ARRAY['continent'::character varying, 'country'::character varying, 'division'::character varying])::text[]))),
    CONSTRAINT ck_sys_area_level CHECK (((level >= 1) AND (level <= 5)))
);

-- @phase constr
ALTER TABLE ONLY public.sys_area
    ADD CONSTRAINT sys_area_pkey PRIMARY KEY (code);

-- @phase idx
CREATE INDEX idx_sys_area_kind_level ON public.sys_area USING btree (kind, level);

CREATE INDEX idx_sys_area_parent ON public.sys_area USING btree (parent_code);

CREATE INDEX idx_sys_area_source ON public.sys_area USING btree (source);

-- @phase fk
ALTER TABLE ONLY public.sys_area
    ADD CONSTRAINT fk_sys_area_parent FOREIGN KEY (parent_code) REFERENCES public.sys_area(code);

-- @phase comment
COMMENT ON TABLE public.sys_area IS '地理地区树：洲与次区域（continent）/ 国家（country）/ 行政区划（division）自引用一体表';

COMMENT ON COLUMN public.sys_area.code IS '主码：洲与次区域=UN M.49（142 亚洲 / 030 东亚）/ 国家=ISO 3166-1 alpha-2（CN）/ 一级区划=ISO 3166-2（CN-BJ）/ 二级及以下=统计码带国家前缀（CN-110100）';

COMMENT ON COLUMN public.sys_area.kind IS '类别：continent 洲与次区域 / country 国家 / division 行政区划（判据列，不要靠 level 推）';

COMMENT ON COLUMN public.sys_area.level IS '层级：1 洲 2 次区域 3 国家 4 省级 5 地级（仅用于缩进与排序）；kind=''continent'' 同时涵盖洲与次区域，两者只能靠 level 区分（1 洲 / 2 次区域）';

COMMENT ON COLUMN public.sys_area.parent_code IS '父级 code（洲为空）；自引用外键';

COMMENT ON COLUMN public.sys_area.name_zh IS '中文名（本系统自有口径，不取第三方立场）';

COMMENT ON COLUMN public.sys_area.name_en IS '英文名';

COMMENT ON COLUMN public.sys_area.iso_code IS '对外对接用国际码：国家=ISO 3166-1（HK/MO/TW），一级区划=ISO 3166-2';

COMMENT ON COLUMN public.sys_area.alpha3 IS '国家三位码（ISO 3166-1 alpha-3，仅国家行）';

COMMENT ON COLUMN public.sys_area.numeric_code IS 'ISO 3166-1 数字码（仅国家行）';

COMMENT ON COLUMN public.sys_area.dial_code IS '国际电话区号（仅国家行）';

COMMENT ON COLUMN public.sys_area.default_currency IS '默认货币 code（仅国家行，**非强关联**：只作表单预填，不参与校验）';

COMMENT ON COLUMN public.sys_area.default_lang IS '默认语言 code（仅国家行，**非强关联**：只作表单预填，不参与校验）';

COMMENT ON COLUMN public.sys_area.source IS '数据来源批次：iso3166 / dr5hn / modood-cn / manual（重灌按它限定范围）';

COMMENT ON COLUMN public.sys_area.enabled IS '是否启用（停用即不在下拉出现，不物理删除）';

COMMENT ON COLUMN public.sys_area.sort_order IS '同父级内的展示顺序';

-- @phase data
